        );
        lampHousing.position.set(l * 3.1, 5.32, 0.1);
        group.add(lampHousing);
        const glow = glowSprite(l === 0 ? 0xfff0cf : 0x9ceeff, l === 0 ? 2.2 : 1.5, 0.9);
        glow.position.set(l * 3.1, 5.16, 0.16);
        group.add(glow);
        this.neonSprites.push(glow);
