    [-1.03, 1.03].forEach((x) => {
      addBox(root, [0.12, 0.95, 0.12], [x, 0.48, 0], dark);
      addBox(root, [0.42, 0.08, 0.42], [x, 0.04, 0], dark);
    });
    addBox(root, [2.26, 0.06, 0.1], [0, 0.93, 0], dark);
    const panel = new THREE.Mesh(new THREE.PlaneGeometry(2.12, 0.6), panelMat);
    panel.position.set(0, 0.63, 0.065);
    root.add(panel);
    const backPanel = panel.clone();
    backPanel.rotation.y = Math.PI;
    backPanel.position.z = -0.065;
    root.add(backPanel);

    [-0.92, 0.92].forEach((x) => {
      const lamp = new THREE.Mesh(new THREE.SphereGeometry(0.065, 8, 6), lampMat);
      lamp.position.set(x, 0.97, 0);
      root.add(lamp);
      const glow = glowSprite(0xff9d2e, 0.8, 0.8);
      glow.position.set(x, 0.97, 0.08);
      root.add(glow);
    });

    root.userData = { width: 2.2, depth: 0.7, type: 'barrier' };
    return root;
  }

  makeLowbar() {
    const root = new THREE.Group();
    root.name = 'lowbar';
    const dark = new THREE.MeshStandardMaterial({ color: 0x222430, roughness: 0.5, metalness: 0.65 });
    const panelMat = new THREE.MeshBasicMaterial({ map: lowbarTexture(), toneMapped: false });

    [-1.24, 1.24].forEach((x) => {
      addBox(root, [0.11, 1.67, 0.11], [x, 0.835, 0], dark);
      addBox(root, [0.44, 0.08, 0.44], [x, 0.04, 0], dark);
    });
    addBox(root, [2.58, 0.12, 0.24], [0, 1.64, 0], dark);
    addBox(root, [2.4, 0.08, 0.18], [0, 1.89, 0], dark);
    const panel = new THREE.Mesh(new THREE.PlaneGeometry(2.3, 0.58), panelMat);
    panel.position.set(0, 1.55, 0.14);
    root.add(panel);

    // Small blinking hazard beacons.
    [-1.14, 1.14].forEach((x) => {
      const glow = glowSprite(0xff7b2c, 0.85, 0.75);
      glow.position.set(x, 1.94, 0.1);
      root.add(glow);
    });

    root.userData = { width: 2.4, depth: 0.55, type: 'lowbar' };
    return root;
  }

  makePowerup(type) {
    const root = new THREE.Group();
    root.name = 'powerup';
    root.userData = { type, width: 1, depth: 1 };
    const cyan = type === 'magnet';
    const color = cyan ? 0x20d9ee : 0xa28aff;
    const coreMat = new THREE.MeshStandardMaterial({
      color,
      emissive: color,
      emissiveIntensity: 2.6,
      metalness: 0.2,
      roughness: 0.2,
    });
    const core = new THREE.Mesh(new THREE.OctahedronGeometry(0.3, 0), coreMat);
    core.position.y = 1.04;
    core.rotation.set(0.4, 0.2, 0);
    root.add(core);

    const ringMat = new THREE.MeshBasicMaterial({
      color,
      transparent: true,
      opacity: 0.52,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      toneMapped: false,
    });
    for (let i = 0; i < 3; i += 1) {
      const ring = new THREE.Mesh(new THREE.TorusGeometry(0.44 + i * 0.07, 0.012, 4, 40), ringMat);
      ring.position.y = 1.04;
      ring.rotation.x = Math.PI / 2 + i * 0.55;
      ring.rotation.y = i * 0.7;
      root.add(ring);
    }

    const glow = glowSprite(color, 3.4, 0.55);
    glow.position.y = 1.04;
    root.add(glow);

    const label = new THREE.Sprite(
      new THREE.SpriteMaterial({
        map: powerupTexture(type),
        transparent: true,
        depthWrite: false,
        toneMapped: false,
      })
    );
    label.scale.set(0.95, 0.95, 1);
    label.position.y = 1.04;
    root.add(label);

    const beam = new THREE.Mesh(
      new THREE.CylinderGeometry(0.025, 0.2, 2.1, 8, 1, true),
      new THREE.MeshBasicMaterial({
        color,
        transparent: true,
        opacity: 0.12,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        side: THREE.DoubleSide,
        toneMapped: false,
      })
    );
    beam.position.y = 0.35;
    root.add(beam);
    return root;
  }

  createObstacle(type) {
    const template =
      type === 'train'
        ? this.trainTemplates[Math.floor(Math.random() * this.trainTemplates.length)]
        : type === 'barrier'
          ? this.barrierTemplate
          : this.lowbarTemplate;
    const group = template.clone(true);
    group.userData = { ...template.userData };
    return group;
  }

  createPowerup(type) {
    const group = this.powerupTemplates[type].clone(true);
    group.userData = { type, width: 1, depth: 1 };
    return group;
  }

  createCoin() {
    const group = new THREE.Group();
    group.name = 'coin';
    const face = new THREE.Mesh(this.coinGeometry, this.coinMaterial);
    face.rotation.x = Math.PI / 2;
    face.castShadow = false;
    group.add(face);
    const rim = new THREE.Mesh(this.coinRimGeometry, this.coinEdgeMaterial);
    rim.castShadow = false;
    group.add(rim);
    const center = new THREE.Mesh(
      new THREE.CircleGeometry(0.16, 18),
      new THREE.MeshBasicMaterial({ color: 0xfff2ae, toneMapped: false })
    );
    center.position.z = 0.045;
    group.add(center);
    const centerBack = center.clone();
    centerBack.position.z = -0.045;
    centerBack.rotation.y = Math.PI;
    group.add(centerBack);
    const glow = glowSprite(0xffc23c, 1.15, 0.38);
    group.add(glow);
    return group;
  }
}

import { formatCompact, formatScore } from './utils.js';

const $ = (selector) => document.querySelector(selector);

export class UI {
  constructor() {
    this.body = document.body;
    this.el = {
      loading: $('#loading'),
      menu: $('#menu'),
      hud: $('#hud'),
      countdown: $('#countdown'),
      countdownNum: $('#countdown-num'),
      pause: $('#pause'),
      gameover: $('#gameover'),
      howto: $('#howto'),
      touch: $('#touch-controls'),
      flash: $('#flash'),
      hitVignette: $('#hit-vignette'),
      toastLayer: $('#toast-layer'),
      score: $('#score'),
      distance: $('#distance'),
      coins: $('#coins'),
      multiplier: $('#multiplier'),
      bestLive: $('#best-live'),
      bestMenu: $('#menu-best'),
      bestMenu2: $('#menu-best-2'),
      coinsMenu: $('#menu-coins'),
      runsMenu: $('#menu-runs'),
      speed: $('#speed-readout'),
      speedFill: $('#speed-fill'),
      comboBlock: $('#combo-block'),
      combo: $('#combo'),
      comboFill: $('#combo-fill'),
      tutorial: $('#tutorial-strip'),
      magnet: $('#powerup-magnet'),
      shield: $('#powerup-shield'),
      magnetFill: $('#powerup-magnet em'),
      shieldFill: $('#powerup-shield em'),
      finalScore: $('#final-score'),
      finalDistance: $('#final-distance'),
      finalCoins: $('#final-coins'),
      finalBest: $('#final-best'),
      newBest: $('#new-best'),
      gameoverTip: $('#gameover-tip'),
      btnPlay: $('#btn-play'),
      btnHow: $('#btn-how'),
      btnHowPlay: $('#btn-how-play'),
      btnCloseHow: $('#btn-close-how'),
      btnPause: $('#btn-pause'),
      btnResume: $('#btn-resume'),
      btnQuit: $('#btn-quit'),
      btnRetry: $('#btn-retry'),
      btnMenu: $('#btn-menu'),
      btnAudio: $('#btn-audio'),
      btnAudioMenu: $('#btn-audio-menu'),
    };
    this.tutorialHidden = false;
    this.toastCount = 0;
  }

  finishLoading() {
    this.el.loading.classList.add('is-done');
  }

  showMenu() {
    this.el.menu.classList.remove('hidden');
    this.el.hud.classList.remove('show');
    this.el.pause.classList.add('hidden');
    this.el.gameover.classList.add('hidden');
    this.el.howto.classList.add('hidden');
    this.body.dataset.state = 'menu';
  }

  hideMenu() {
    this.el.menu.classList.add('hidden');
  }

  showHud() {
    this.el.hud.classList.add('show');
  }

  hideHud() {
    this.el.hud.classList.remove('show');
  }

  setMenuStats(save) {
    this.el.bestMenu.textContent = formatScore(save.best);
    this.el.bestMenu2.textContent = formatCompact(save.best);
    this.el.coinsMenu.textContent = formatCompact(save.coins);
    this.el.runsMenu.textContent = formatCompact(save.runs);
  }

  setBestLive(best) {
    this.el.bestLive.textContent = `BEST ${formatScore(best)}`;
  }

  updateHud(state) {
    this.el.score.textContent = formatScore(state.score);
    this.el.distance.textContent = Math.floor(state.distance).toLocaleString('en-US');
    this.el.coins.textContent = state.coins.toLocaleString('en-US');
    this.el.multiplier.textContent = `x${state.multiplier}`;
    this.el.bestLive.textContent = `BEST ${formatScore(Math.max(state.best, state.score))}`;
    this.el.speed.innerHTML = `${Math.floor(state.speed * 3.6)}<small> km/h</small>`;
    this.el.speedFill.style.width = `${Math.round(state.speedFraction * 100)}%`;

    if (state.combo > 0) {
      this.el.comboBlock.classList.add('active');
      this.el.combo.textContent = state.combo;
      this.el.comboFill.style.transform = `scaleX(${Math.max(0, state.comboTime / 2.6)})`;
    } else {
      this.el.comboBlock.classList.remove('active');
    }

    this.updatePowerup(this.el.magnet, this.el.magnetFill, state.magnetTime, 10);
    this.updatePowerup(this.el.shield, this.el.shieldFill, state.shieldTime, 12);
  }

  updatePowerup(element, fill, time, total) {
    element.classList.toggle('active', time > 0);
    if (time > 0) fill.style.transform = `scaleX(${Math.min(1, time / total)})`;
  }

  hideTutorial() {
    if (this.tutorialHidden) return;
    this.tutorialHidden = true;
    this.el.tutorial.classList.add('hide');
  }

  resetTutorial() {
    this.tutorialHidden = false;
    this.el.tutorial.classList.remove('hide');
  }

  setCountdown(value, go = false) {
    this.el.countdown.classList.add('show');
    this.el.countdown.classList.toggle('go', go);
    this.el.countdownNum.textContent = value;
    this.el.countdownNum.classList.remove('pop');
    // Force a reflow so the pop animation can replay for each numeral.
    void this.el.countdownNum.offsetWidth;
    this.el.countdownNum.classList.add('pop');
  }

  hideCountdown() {
    this.el.countdown.classList.remove('show', 'go');
  }

  showPause() {
    this.el.pause.classList.remove('hidden');
  }

  hidePause() {
    this.el.pause.classList.add('hidden');
  }

  showGameOver(data) {
    this.el.finalScore.textContent = formatScore(data.score);
    this.el.finalDistance.innerHTML = `${Math.floor(data.distance).toLocaleString('en-US')}<small>m</small>`;
    this.el.finalCoins.textContent = data.coins.toLocaleString('en-US');
    this.el.finalBest.textContent = formatScore(data.best);
    this.el.newBest.classList.toggle('show', data.newBest);
    this.el.gameoverTip.textContent = data.tip;
    this.el.gameover.classList.remove('hidden');
    this.body.dataset.state = 'gameover';
  }

  hideGameOver() {
    this.el.gameover.classList.add('hidden');
  }

  showHowto() {
    this.el.howto.classList.remove('hidden');
  }

  hideHowto() {
    this.el.howto.classList.add('hidden');
  }

  setAudioMuted(muted) {
    this.el.btnAudio.classList.toggle('muted', muted);
    this.el.btnAudioMenu.classList.toggle('muted', muted);
    const label = muted ? 'Unmute sound' : 'Mute sound';
    this.el.btnAudio.setAttribute('aria-label', label);
    this.el.btnAudioMenu.setAttribute('aria-label', label);
  }

  flash() {
    this.el.flash.classList.remove('fire');
    void this.el.flash.offsetWidth;
    this.el.flash.classList.add('fire');
  }

  hitFlash() {
    this.el.hitVignette.classList.remove('fire');
    void this.el.hitVignette.offsetWidth;
    this.el.hitVignette.classList.add('fire');
  }

  toast(text, variant = '') {
    if (this.toastCount > 4) return;
    this.toastCount += 1;
    const node = document.createElement('div');
    node.className = `toast ${variant}`.trim();
    node.textContent = text;
    this.el.toastLayer.appendChild(node);
    window.setTimeout(() => {
      node.remove();
      this.toastCount -= 1;
    }, 1550);
  }

  setTouchVisible(visible) {
    this.el.touch.style.display = visible ? 'flex' : 'none';
  }
}

import * as THREE from 'three';
import { World } from './world.js';
import { Runner } from './runner.js';
import { SoundEngine } from './audio.js';
import { AssetFactory, LANES } from './templates.js';
import { UI } from './ui.js';
import {
  clamp,
  damp,
  formatScore,
  lerp,
  pick,
  rand,
  randInt,
  shuffle,
} from './utils.js';

const PLAYER_Z = 0;
const BASE_SPEED = 16;
const MAX_SPEED = 43;
const GRAVITY = 33;
const JUMP_VELOCITY = 10.8;
const SPAWN_Z = -148;
const SAVE_KEY = 'railrush-save-v1';
const POWERUP_DURATION = { magnet: 10, shield: 12 };

const TIPS = [
  'TIP / Slide under low signs. Jump the striped barriers.',
  'TIP / Chain coins quickly to raise your multiplier to x5.',
  'TIP / Thread past a train in the next lane for a near-miss bonus.',
  'TIP / A shield eats one crash. Save it for a double train.',
  'TIP / The magnet sweeps coins from every lane. Ride the trail.',
  'TIP / Don’t fight the speed. Learn the rhythm of the line.',
];

export class Game {
  constructor(canvas) {
    this.canvas = canvas;
    this.state = 'menu';
    this.time = 0;
    this.lastFrame = performance.now();
    this.countdownTimers = [];
    this.effects = [];
    this.obstacles = [];
    this.powerups = [];
    this.coins = [];
    this.coinPool = [];
    this.deathTimer = 0;
    this.gameOverTimer = null;
    this.hudTick = 0;
    this.menuTime = 0;
    this.pointer = new THREE.Vector2();

    this.renderer = new THREE.WebGLRenderer({
      canvas,
      antialias: true,
      alpha: false,
      powerPreference: 'high-performance',
      stencil: false,
    });
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.8));
    this.renderer.setSize(window.innerWidth, window.innerHeight, false);
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.07;
    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;

    this.scene = new THREE.Scene();
    this.scene.background = new THREE.Color(0x070813);
    this.scene.fog = new THREE.Fog(0x0a0b1d, 52, 205);

    this.camera = new THREE.PerspectiveCamera(61, window.innerWidth / window.innerHeight, 0.1, 520);
    this.camera.position.set(6.6, 5.2, 14.5);
    this.cameraLook = new THREE.Vector3(-2.6, 1.3, -25);
    this.cameraPosition = this.camera.position.clone();

    this.world = new World(this.scene);
    this.runner = new Runner(this.scene);
    this.assets = new AssetFactory();
    this.sound = new SoundEngine();
    this.ui = new UI();
    this.ui.setAudioMuted(this.sound.muted);

    this.save = this.loadSave();
    this.ui.setMenuStats(this.save);
    this.ui.setBestLive(this.save.best);

    this.buildCoinPool();
    this.bindUI();
    this.bindInput();
    this.resize();
    this.setupMenuScene();
    this.ui.showMenu();
    this.ui.finishLoading();
    this.sound.setMuted(this.sound.muted);

    // A tiny test/debug handle keeps the game inspectable without affecting play.
    window.__RAIL_RUSH__ = this;

    this.loop = this.loop.bind(this);
    this.lastFrame = performance.now();
    requestAnimationFrame(this.loop);
  }

  loadSave() {
    const fallback = { best: 0, coins: 0, runs: 0 };
    try {
      const raw = JSON.parse(localStorage.getItem(SAVE_KEY) || 'null');
      if (!raw || typeof raw !== 'object') return fallback;
      return {
        best: Number.isFinite(raw.best) ? raw.best : 0,
        coins: Number.isFinite(raw.coins) ? raw.coins : 0,
        runs: Number.isFinite(raw.runs) ? raw.runs : 0,
      };
    } catch {
      return fallback;
    }
  }

  saveProgress() {
    try {
      localStorage.setItem(SAVE_KEY, JSON.stringify(this.save));
    } catch {
      // Storage can be unavailable in private windows; the run still works.
    }
  }

  buildCoinPool() {
    for (let i = 0; i < 80; i += 1) {
      const coin = this.assets.createCoin();
      coin.visible = false;
      coin.userData.pooled = true;
      this.scene.add(coin);
      this.coinPool.push(coin);
    }
  }

  bindUI() {
    const click = (element, handler) => {
      element?.addEventListener('click', (event) => {
        event.preventDefault();
        this.sound.init();
        this.sound.click();
        handler(event);
      });
    };

    click(this.ui.el.btnPlay, () => this.startRun());
    click(this.ui.el.btnHow, () => this.ui.showHowto());
    click(this.ui.el.btnCloseHow, () => this.ui.hideHowto());
    click(this.ui.el.btnHowPlay, () => {
      this.ui.hideHowto();
      this.startRun();
    });
    click(this.ui.el.btnPause, () => this.pauseGame());
    click(this.ui.el.btnResume, () => this.resumeGame());
    click(this.ui.el.btnQuit, () => this.quitToMenu());
    click(this.ui.el.btnRetry, () => this.startRun());
    click(this.ui.el.btnMenu, () => this.quitToMenu());
    click(this.ui.el.btnAudio, () => this.toggleAudio());
    click(this.ui.el.btnAudioMenu, () => this.toggleAudio());

    this.ui.el.touch.querySelectorAll('[data-action]').forEach((button) => {
      button.addEventListener('pointerdown', (event) => {
        event.preventDefault();
        event.stopPropagation();
        this.doAction(button.dataset.action);
      });
    });
  }

  toggleAudio() {
    const muted = this.sound.toggleMuted();
    this.ui.setAudioMuted(muted);
    if (!muted) this.sound.click();
  }

  bindInput() {
    window.addEventListener('keydown', (event) => this.onKeyDown(event), { passive: false });
    window.addEventListener('resize', () => this.resize());
    window.addEventListener('blur', () => {
      if (this.state === 'playing') this.pauseGame();
    });
    document.addEventListener('visibilitychange', () => {
      if (document.hidden && this.state === 'playing') this.pauseGame();
    });

    const canvas = this.canvas;
    let touchStart = null;
    canvas.addEventListener('pointerdown', (event) => {
      if (event.pointerType === 'mouse' && event.button !== 0) return;
      touchStart = { x: event.clientX, y: event.clientY, at: performance.now(), id: event.pointerId };
      if (canvas.setPointerCapture) canvas.setPointerCapture(event.pointerId);
    });
    canvas.addEventListener('pointerup', (event) => {
      if (!touchStart || touchStart.id !== event.pointerId) return;
      const dx = event.clientX - touchStart.x;
      const dy = event.clientY - touchStart.y;
      const elapsed = performance.now() - touchStart.at;
      touchStart = null;
      if (this.state !== 'playing' || elapsed > 800) return;
      const threshold = Math.max(18, Math.min(window.innerWidth, window.innerHeight) * 0.028);
      if (Math.abs(dx) < threshold && Math.abs(dy) < threshold) return;
      if (Math.abs(dx) > Math.abs(dy)) {
        this.doAction(dx > 0 ? 'right' : 'left');
      } else {
        this.doAction(dy > 0 ? 'slide' : 'jump');
      }
    });
    canvas.addEventListener('pointercancel', () => {
      touchStart = null;
    });
    canvas.addEventListener('pointermove', (event) => {
      if (event.pointerType === 'mouse') {
        this.pointer.set(
          (event.clientX / window.innerWidth) * 2 - 1,
          (event.clientY / window.innerHeight) * 2 - 1
        );
      }
    });
  }

  onKeyDown(event) {
    const key = event.key.toLowerCase();
    const code = event.code;
    const isUiKey = [' ', 'arrowup', 'arrowdown', 'arrowleft', 'arrowright'].includes(key);
    if (isUiKey) event.preventDefault();
    if (event.repeat) return;

    if (this.state === 'playing') {
      if (key === 'a' || code === 'ArrowLeft') this.doAction('left');
      else if (key === 'd' || code === 'ArrowRight') this.doAction('right');
      else if (key === 'w' || code === 'ArrowUp' || code === 'Space') this.doAction('jump');
      else if (key === 's' || code === 'ArrowDown') this.doAction('slide');
      else if (key === 'p' || key === 'escape') this.pauseGame();
      else if (key === 'm') this.toggleAudio();
      return;
    }

    if (this.state === 'paused') {
      if (key === 'p' || key === 'escape') this.resumeGame();
      else if (key === 'm') this.toggleAudio();
      return;
    }

    if (this.state === 'menu') {
      if (!this.ui.el.howto.classList.contains('hidden')) {
        if (key === 'escape') this.ui.hideHowto();
        return;
      }
      if (key === 'enter' || key === ' ') this.startRun();
      else if (key === 'm') this.toggleAudio();
      return;
    }

    if (this.state === 'gameover') {
      if (key === 'r' || key === 'enter' || key === ' ') this.startRun();
      else if (key === 'escape') this.quitToMenu();
      else if (key === 'm') this.toggleAudio();
    }
  }

  resize() {
    const width = window.innerWidth;
    const height = window.innerHeight;
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.8));
    this.renderer.setSize(width, height, false);
    this.camera.aspect = width / height;
    this.camera.updateProjectionMatrix();
  }

  doAction(action) {
    if (this.state !== 'playing') return;
    if (action === 'left') this.switchLane(-1);
    else if (action === 'right') this.switchLane(1);
    else if (action === 'jump') this.jump();
    else if (action === 'slide') this.slide();
    if (this.travel > 8) this.ui.hideTutorial();
  }

  switchLane(direction) {
    const next = clamp(this.targetLane + direction, 0, 2);
    if (next === this.targetLane) {
      this.laneNudge = direction * 0.06;
      return;
    }
    this.targetLane = next;
    this.sound.lane();
    this.shake = Math.max(this.shake, 0.025);
  }

  jump() {
    if (!this.grounded) return;
    this.grounded = false;
    this.verticalVelocity = JUMP_VELOCITY;
    this.rollTimer = 0;
    this.jumpStretch = 1;
    this.sound.jump();
  }

  slide() {
    if (this.grounded) {
      this.rollTimer = 0.68;
      this.sound.slide();
    } else {
      this.verticalVelocity = Math.min(this.verticalVelocity, -13);
      this.rollTimer = 0.42;
    }
    this.ui.hideTutorial();
  }

  startRun() {
    if (this.state === 'countdown') return;
    this.cancelCountdown();
    this.sound.init();
    this.sound.startMusic();
    this.state = 'countdown';
    this.deathTimer = 0;
    this.resetRun();
    this.ui.hideMenu();
    this.ui.hideGameOver();
    this.ui.hidePause();
    this.ui.hideHowto();
    this.ui.showHud();
    this.ui.resetTutorial();
    this.ui.setTouchVisible(true);
    this.ui.setBestLive(this.save.best);
    this.bodyState('countdown');

    this.ui.setCountdown('3');
    this.sound.countdown();
    const sequence = [
      [650, '2', false],
      [1300, '1', false],
      [1950, 'GO', true],
      [2520, null, false],
    ];
    sequence.forEach(([delay, label, go], index) => {
      const timer = window.setTimeout(() => {
        if (this.state !== 'countdown') return;
        if (label) {
          this.ui.setCountdown(label, go);
          this.sound.countdown(go);
        }
        if (index === sequence.length - 1) {
          this.ui.hideCountdown();
          this.beginPlaying();
        }
      }, delay);
      this.countdownTimers.push(timer);
    });
  }

  cancelCountdown() {
    this.countdownTimers.forEach((timer) => window.clearTimeout(timer));
    this.countdownTimers = [];
  }

  beginPlaying() {
    if (this.state !== 'countdown') return;
    this.state = 'playing';
    this.bodyState('playing');
    this.ui.hideCountdown();
    this.speed = BASE_SPEED;
    this.seedCourse();
    this.ui.toast('RUN THE LINE // GOOD LUCK', 'cyan');
  }

  resetRun() {
    this.clearEntities();
    this.runner.reset();
    this.playerX = 0;
    this.targetLane = 1;
    this.currentLane = 1;
    this.jumpY = 0;
    this.verticalVelocity = 0;
    this.grounded = true;
    this.rollTimer = 0;
    this.speed = BASE_SPEED;
    this.distance = 0;
    this.travel = 0;
    this.score = 0;
    this.bonusScore = 0;
    this.coinsCollected = 0;
    this.combo = 0;
    this.comboTimer = 0;
    this.multiplier = 1;
    this.magnetTime = 0;
    this.shieldTime = 0;
    this.invincible = 0;
    this.elapsed = 0;
    this.nextSpawnTravel = 55;
    this.waveIndex = 0;
    this.isNewBest = false;
    this.newBestAnnounced = false;
    this.lastNearMissAt = -10;
    this.shake = 0;
    this.cameraFov = 61;
    this.deathTimer = 0;
    this.hudTick = 0;
    this.ui.hideTutorial();
    this.ui.setBestLive(this.save.best);
    this.updateHud(true);
  }

  pauseGame() {
    if (this.state !== 'playing') return;
    this.state = 'paused';
    this.bodyState('paused');
    this.ui.showPause();
    this.sound.setPaused(true);
  }

  resumeGame() {
    if (this.state !== 'paused') return;
    this.state = 'playing';
    this.bodyState('playing');
    this.ui.hidePause();
    this.sound.setPaused(false);
    this.lastFrame = performance.now();
  }

  quitToMenu() {
    this.cancelCountdown();
    this.state = 'menu';
    this.clearEntities();
    this.runner.reset();
    this.runner.group.position.set(0, 0, 0);
    this.ui.hideHud();
    this.ui.hidePause();
    this.ui.hideGameOver();
    this.ui.hideCountdown();
    this.ui.hideHowto();
    this.ui.setTouchVisible(false);
    this.ui.setMenuStats(this.save);
    this.ui.showMenu();
    this.bodyState('menu');
    this.sound.stopMusic();
    this.sound.setPaused(false);
    this.setupMenuScene();
    this.menuTime = 0;
  }

  bodyState(state) {
    document.body.dataset.state = state;
    this.state = state;
  }

  setupMenuScene() {
    const train = this.spawnObstacle('train', 2, -34, true);
    train.group.rotation.z = 0.008;
    const trainFar = this.spawnObstacle('train', 0, -82, true);
    trainFar.group.rotation.z = -0.006;
    this.spawnObstacle('barrier', 1, -54, true);
    this.spawnObstacle('lowbar', 1, -108, true);
    this.spawnCoinLine([2], -18, 8, 1.55, 'straight');
    this.spawnCoinLine([1], -63, 7, 1.65, 'arc');
    this.spawnPowerup(2, -74, 'magnet', true);
    this.menuDecorMoney = this.coins.slice();
  }

  // __SECOND_HALF__
}

