import { Game } from './game.js';

async function boot() {
  const canvas = document.querySelector('#game-canvas');
  try {
    // Textures used on in-game signage and the backpack are drawn with canvas
    // text, so wait for the display font before generating them.
    await document.fonts.ready;
  } catch {
    // Older browsers still get the system font fallback.
  }

  try {
    const game = new Game(canvas);
    game.camera.lookAt(game.cameraLook);
    window.addEventListener('contextmenu', (event) => {
      if (event.target === canvas) event.preventDefault();
    });
  } catch (error) {
    console.error(error);
    const loading = document.querySelector('#loading');
    if (loading) {
      loading.innerHTML = `
        <div class="loading-mark"><span>R</span><span>R</span></div>
        <div class="loading-text" style="max-width:320px;text-align:center;line-height:1.8">
          THIS LINE NEEDS WEBGL<br />
          <span style="opacity:.6">Enable hardware acceleration or try a modern browser.</span>
        </div>
      `;
      loading.classList.remove('is-done');
    }
  }
}

boot();
import { clamp } from './utils.js';

/**
 * Tiny procedural sound engine. Everything is synthesised in the browser, so
 * the game has no external audio dependencies and can start instantly.
 */
export class SoundEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.sfxBus = null;
    this.musicBus = null;
    this.muted = localStorage.getItem('railrush-muted') === '1';
    this.musicPlaying = false;
    this.scheduler = null;
    this.nextNoteTime = 0;
    this.step = 0;
    this.energy = 0;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AudioCtor = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtor) return;
    this.ctx = new AudioCtor();

    const compressor = this.ctx.createDynamicsCompressor();
    compressor.threshold.value = -18;
    compressor.knee.value = 22;
    compressor.ratio.value = 5;
    compressor.attack.value = 0.005;
    compressor.release.value = 0.22;
    compressor.connect(this.ctx.destination);

    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.58;
    this.master.connect(compressor);

    this.sfxBus = this.ctx.createGain();
    this.sfxBus.gain.value = 0.8;
    this.sfxBus.connect(this.master);

    this.musicBus = this.ctx.createGain();
    this.musicBus.gain.value = 0;
    this.musicBus.connect(this.master);
  }

